import{_ as e,c as a,o as r,aj as t}from"./chunks/framework.lC5GZWV9.js";const k=JSON.parse('{"title":"Books","description":"","frontmatter":{},"headers":[],"relativePath":"guides/books.md","filePath":"guides/books.md","lastUpdated":1790237196000}'),l={name:"guides/books.md"};function s(n,o,i,c,d,h){return r(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="books" tabindex="-1">Books <a class="header-anchor" href="#books" aria-label="Permalink to “Books”">​</a></h1><p>The default provider that Ryot uses for book tracking is <a href="https://openlibrary.org" target="_blank" rel="noreferrer">Openlibrary</a>. You might find it lacking in some cases, so Ryot also supports other providers.</p><h2 id="hardcover" tabindex="-1">Hardcover <a class="header-anchor" href="#hardcover" aria-label="Permalink to “Hardcover”">​</a></h2><p>Ryot supports tracking books via <a href="https://hardcover.app" target="_blank" rel="noreferrer">Hardcover</a>. As of writing, the API key expires after a year or on January 1st, so you will need to renew it accordingly.</p><p>You can use the following steps to obtain your own API keys:</p><ol><li>Create a <a href="https://hardcover.app" target="_blank" rel="noreferrer">Hardcover</a> account.</li><li>Open <a href="https://hardcover.app/account/api" target="_blank" rel="noreferrer">API Access</a> and create an API key using the <code>Read-Only Stats / Export</code> preset.</li><li>Set it as <code>BOOKS_HARDCOVER_API_KEY</code>.</li></ol><h2 id="google-books" tabindex="-1">Google Books <a class="header-anchor" href="#google-books" aria-label="Permalink to “Google Books”">​</a></h2><p>Ryot also supports tracking books via <a href="https://books.google.com" target="_blank" rel="noreferrer">Google Books</a>. You can follow the below steps to obtain your own API keys and enable book tracking with Google Books.</p><ol><li>Create a <a href="https://cloud.google.com" target="_blank" rel="noreferrer">Google Cloud Platform</a> account. Open your <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">Google Cloud Platform Console</a>.</li><li>Use the default project or click on &quot;Create a project&quot; on the dashboard.</li><li>Open the <a href="https://console.cloud.google.com/apis/dashboard" target="_blank" rel="noreferrer">APIs &amp; Services Dashboard</a>.</li><li>Click on &quot;Enable APIs and Services&quot;. Search for &quot;Google Books API&quot; and click on &quot;Enable&quot;.</li><li>Click on &quot;Credentials&quot; on the left sidebar. Click on &quot;Create Credentials&quot; and select &quot;API key&quot;.</li><li>Click on &quot;Create&quot; and copy the API key.</li><li>Set the <code>BOOKS_GOOGLE_BOOKS_API_KEY</code> environment variable as described in the <a href="./../configuration.html">configuration</a> docs.</li></ol>',9)])])}const u=e(l,[["render",s]]);export{k as __pageData,u as default};
